(function(){var mcCvs=document.getElementById('mc_cvs');if(!mcCvs)return;var trades=[],srcLabel='[E] Parâmetros Manuais';function rng(seed){var s=seed%2147483647;if(s<=0)s+=2147483646;return function(){s=s*16807%2147483647;return(s-1)/2147483646;};}function parseNum(v){if(v==null)return NaN;var s=String(v).replace(/[^0-9,.-]/g,'').trim();if(!s)return NaN;if(s.indexOf(',')>-1&&s.indexOf('.')>-1){s=s.lastIndexOf(',')>s.lastIndexOf('.')?s.replace(/\./g,'').replace(',','.'):s.replace(/,/g,'');}else if(s.indexOf(',')>-1){s=s.replace(',','.');}return parseFloat(s);}function parseCSV(txt){var lines=txt.split(/\r?\n/).filter(function(l){return l.trim();});if(lines.length<2)return[];var sep=(lines[0].split(';').length>lines[0].split(',').length)?';':',';var hdr=lines[0].split(sep).map(function(h){return h.toLowerCase().trim();});var iPnl=hdr.findIndex(function(h){return /profit|lucro|pnl|net|resultado/.test(h);});var iCom=hdr.findIndex(function(h){return /comm|comiss/.test(h);});var iSwp=hdr.findIndex(function(h){return /swap/.test(h);});var iSym=hdr.findIndex(function(h){return /symbol|ativo|item|par/.test(h);});var iDat=hdr.findIndex(function(h){return /time|date|data|close/.test(h);});if(iPnl<0)iPnl=hdr.length-1;var raw=[];for(var i=1;i<lines.length;i++){var cols=lines[i].split(sep);if(cols.length<=iPnl)continue;var pnl=parseNum(cols[iPnl]);if(isNaN(pnl))continue;var com=iCom>=0?(parseNum(cols[iCom])||0):0;var swp=iSwp>=0?(parseNum(cols[iSwp])||0):0;raw.push({date:(iDat>=0?cols[iDat]:'#'+i),sym:(iSym>=0?cols[iSym]:'CSV'),gross:pnl,cost:Math.abs(com)+Math.abs(swp),net:pnl+com+swp});}if(!raw.length)return[];var losses=raw.filter(function(x){return x.net<0;}).map(function(x){return Math.abs(x.net);});var unit=losses.length?(losses.reduce(function(a,b){return a+b;},0)/losses.length):(Math.abs(raw[0].net)||1);return raw.map(function(x){return{date:x.date,sym:x.sym,rGross:x.gross/unit,rCost:x.cost/unit,rNet:x.net/unit};});}function syncInputs(){if(!trades.length)return;var w=trades.filter(function(t){return t.rNet>0;}),l=trades.filter(function(t){return t.rNet<0;});var wr=(w.length/trades.length)*100;var avgW=w.length?(w.reduce(function(a,b){return a+b.rNet;},0)/w.length):1;var avgL=l.length?Math.abs(l.reduce(function(a,b){return a+b.rNet;},0)/l.length):1;var avgC=trades.reduce(function(a,b){return a+b.rCost;},0)/trades.length;document.getElementById('mc_n').value=trades.length;document.getElementById('mc_wr').value=wr.toFixed(1);document.getElementById('mc_rr').value=(avgW/(avgL||1)).toFixed(2);document.getElementById('mc_cost').value=avgC.toFixed(3);}
function runAudit(){var n=parseInt(document.getElementById('mc_n').value,10)||100;var wr=(parseFloat(document.getElementById('mc_wr').value)||45)/100;var rr=parseFloat(document.getElementById('mc_rr').value)||2.0;var rsk=(parseFloat(document.getElementById('mc_rsk').value)||1.0)/100;var cost=parseFloat(document.getElementById('mc_cost').value)||0;var seed=parseInt(document.getElementById('mc_seed').value,10)||42;var sample=trades.length?trades.map(function(t){return t.rNet;}):null;var expNet=sample?(sample.reduce(function(a,b){return a+b;},0)/sample.length):(wr*rr-(1-wr)*1-cost);var expGross=trades.length?(trades.reduce(function(a,b){return a+b.rGross;},0)/trades.length):(expNet+cost);var ob=document.getElementById('mc_outlier_box');if(ob){var msg='Sem amostra individual carregada: usa o botão CSV ou Diário para medir dependência de outliers.';if(sample&&sample.length>=5){var sorted=sample.slice().sort(function(a,b){return b-a;});var top2=sorted.slice(0,2).reduce(function(a,b){return a+b;},0);var exTop2=(sample.reduce(function(a,b){return a+b;},0)-top2)/(sample.length-2);msg='Expectância Bruta: <b>'+(expGross>=0?'+':'')+expGross.toFixed(3)+' R</b> | Custos médios: <b>-'+cost.toFixed(3)+' R</b> | Expectância Líquida: <b>'+(expNet>=0?'+':'')+expNet.toFixed(3)+' R</b>.<br>Sem os 2 melhores trades (outliers): expectância passa para <b style="color:'+(exTop2>0?'#4ade80':'#f87171')+'">'+(exTop2>=0?'+':'')+exTop2.toFixed(3)+' R/trade</b> ('+(exTop2>0?'Vantagem distribuída — Método consistente':'Dependente de outliers — Risco de sorte concentrada')+').';}ob.innerHTML='<strong style="color:#38bdf8">Diagnóstico de Outliers & Custos (“Método ou Sorte?”)</strong><p style="margin:6px 0 0;font-size:13px">'+msg+'</p>';}var bb=document.getElementById('mc_boot_box');if(bb){var rB=rng(seed+99),means=[],blk=Math.max(2,Math.min(5,Math.floor(n/10)));for(var b=0;b<1000;b++){var sum=0,cnt=0;while(cnt<n){var st=Math.floor(rB()*(sample?sample.length:n));for(var k=0;k<blk&&cnt<n;k++){var val=sample?sample[(st+k)%sample.length]:((rB()<wr?rr:-1)-cost);sum+=val;cnt++;}}means.push(sum/n);}means.sort(function(a,b){return a-b;});var lo=means[25],hi=means[975];bb.innerHTML='<strong style="color:#eab308">Bootstrap por Blocos (1 000 reamostragens, bloco = '+blk+')</strong><p style="margin:6px 0 0;font-size:13px">IC 95% da Expectância Líquida: <b style="color:'+(lo>0?'#4ade80':'#fbbf24')+'">['+(lo>=0?'+':'')+lo.toFixed(3)+' R , '+(hi>=0?'+':'')+hi.toFixed(3)+' R]</b> '+(lo>0?'— Limite inferior acima de zero (significância estatística positiva).':'— Intervalo cruza zero (amostra ainda não descarta acaso).')+'</p>';}
var rM=rng(seed),ctx=mcCvs.getContext('2d'),w=mcCvs.width,h=mcCvs.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#020617';ctx.fillRect(0,0,w,h);var hitUp=0,hitDn=0,mid=0;for(var p=0;p<2000;p++){var eq=1.0,done=false;if(p<45){ctx.beginPath();ctx.moveTo(20,h/2);}for(var t=1;t<=n;t++){var rTrade=sample?sample[Math.floor(rM()*sample.length)]:((rM()<wr?rr:-1)-cost);eq*=(1+rsk*rTrade);if(p<45){var x=20+(t/n)*(w-40),y=h/2-(eq-1)*(h*1.8);ctx.lineTo(x,Math.max(10,Math.min(h-10,y)));}if(!done&&eq>=1.10){hitUp++;done=true;}if(!done&&eq<=0.90){hitDn++;done=true;}}if(!done)mid++;if(p<45){ctx.strokeStyle=eq>=1.10?'rgba(34,197,94,.45)':eq<=0.90?'rgba(239,68,68,.45)':'rgba(148,163,184,.25)';ctx.stroke();}}ctx.strokeStyle='#38bdf8';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(20,h/2);ctx.lineTo(w-20,h/2);ctx.stroke();ctx.setLineDash([]);var pUp=(hitUp/20).toFixed(1),pDn=(hitDn/20).toFixed(1),pMd=(mid/20).toFixed(1);document.getElementById('mc_res_txt').innerHTML='<span class="selo-tag selo-S">[S] 2 000 Caminhos (Semente '+seed+')</span> <b style="color:#22c55e">'+pUp+'% atingiram +10%</b> | <b style="color:#ef4444">'+pDn+'% atingiram -10%</b> | <b>'+pMd+'% intermédios</b>.';var tb=document.getElementById('mc_trades_tb');if(tb)tb.innerHTML=trades.length?trades.slice(0,100).map(function(t,ix){return '<tr><td style="padding:5px">'+(ix+1)+'</td><td style="padding:5px">'+t.date+' ('+t.sym+')</td><td style="padding:5px">'+(t.rGross>=0?'+':'')+t.rGross.toFixed(2)+' R</td><td style="padding:5px;color:#fbbf24">-'+t.rCost.toFixed(2)+' R</td><td style="padding:5px;color:'+(t.rNet>=0?'#22c55e':'#ef4444')+'">'+(t.rNet>=0?'+':'')+t.rNet.toFixed(2)+' R</td></tr>';}).join(''):'<tr><td colspan="5" style="padding:6px">Sem ficheiro CSV/Diário carregado (a usar parâmetros acima).</td></tr>';}document.getElementById('mc_csv_in').onchange=function(ev){var f=ev.target.files[0];if(!f)return;var rd=new FileReader();rd.onload=function(e){var parsed=parseCSV(e.target.result);if(!parsed.length){alert('Não foi possível ler trades válidos neste CSV.');return;}trades=parsed;srcLabel='[U] CSV: '+f.name+' ('+trades.length+' trades lidos)';document.getElementById('mc_src_status').textContent=srcLabel;syncInputs();runAudit();};rd.readAsText(f);};document.getElementById('btn_mc_diario').onclick=function(){var u=[];try{u=JSON.parse(localStorage.getItem('aq_diario_v25')||'[]');}catch(e){}if(!u.length){alert('Ainda não tens trades reais [U] guardados no Guia 4.');return;}trades=u.map(function(t){return{date:t.date,sym:t.sym,rGross:t.r,rCost:0.05,rNet:t.r-0.05};});srcLabel='[U] Diário Local ('+trades.length+' trades lidos)';document.getElementById('mc_src_status').textContent=srcLabel;syncInputs();runAudit();};document.getElementById('btn_mc_demo').onclick=function(){var d=[2.1,-1,-1,2.4,-1,1.8,-1,2.2,-1,-1,2.5,-1,1.9,-1,2.0,-1,-1,2.3,-1,1.7];trades=d.map(function(v,i){return{date:'Amostra #'+(i+1),sym:'BTCUSDT',rGross:v,rCost:0.05,rNet:v-0.05};});srcLabel='[E] Amostra Didática (20 trades)';document.getElementById('mc_src_status').textContent=srcLabel;syncInputs();runAudit();};document.getElementById('btn_mc_run').onclick=runAudit;document.getElementById('btn_mc_rep').onclick=function(){var txt='RELATORIO AUDITORIA QUANT BETA\nData: '+new Date().toISOString().slice(0,10)+'\nOrigem: '+srcLabel+'\n'+document.getElementById('mc_outlier_box').innerText+'\n'+document.getElementById('mc_boot_box').innerText+'\n'+document.getElementById('mc_res_txt').innerText;var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type:'text/plain;charset=utf-8;'}));a.download='relatorio_auditoria_quant.txt';a.click();};document.getElementById('mc_src_status').textContent=srcLabel;runAudit();})();

(function(){var acBox=document.getElementById('acad_lessons_box');if(acBox){var AKEY='aq_academia_v1',st={};try{st=JSON.parse(localStorage.getItem(AKEY)||'{}');}catch(e){}var lessons=[{id:'l1',t:'Lição 1 — Custos de Execução (Spread, Comissão e Slippage)',txt:'Uma estratégia com +0.12 R bruto e custo de 0.14 R por operação tem expectância líquida negativa (-0.02 R). Quanto menor o timeframe, maior o peso dos custos no resultado final.',q:'Adivinha antes de ver: Se ganhas 50% das vezes com payoff 1.2:1, mas pagas 0.15 R de custos por trade, qual é a expectância líquida?',a:'Expectância bruta = (0.50 × 1.2) − (0.50 × 1.0) = +0.10 R. Subtraindo 0.15 R de custos, a expectância líquida cai para -0.05 R por trade (prejuízo estrutural).'},{id:'l2',t:'Lição 2 — Amostra e Acaso (Porque 20 Trades Não Provam Vantagem)',txt:'Numa moeda ao ar equilibrada (expectância 0 R), sequências de 20 lançamentos produzem frequentemente 65% ou 70% de caras por pura variância. Só amostras grandes (n ≥ 100–300) estreitam o intervalo de confiança.',q:'Adivinha antes de ver: Qual é o risco de aumentar o lote após 12 trades seguidos positivos?',a:'Confundir variância favorável de curto prazo com vantagem estatística real, expondo a conta a uma regressão à média com risco elevado.'},{id:'l3',t:'Lição 3 — Assimetria do Drawdown e Dimensionamento',txt:'Perder 10% exige +11.1% para recuperar; perder 50% exige +100%. Limitar o risco fixo por operação (ex.: 0.5% a 1%) impede que uma série negativa normal destrua o capital.',q:'Adivinha antes de ver: Se arriscas 5% por trade e sofres 8 perdas seguidas, quanto resta da conta?',a:'Restam 0.95^8 = 66.3% da conta (-33.7% de drawdown), exigindo +50.8% apenas para voltar ao ponto de partida.'},{id:'l4',t:'Lição 4 — Viés de Seleção e Sobrevivência',txt:'Olhar apenas para os setups que deram certo no passado ou copiar parâmetros otimizados sem período fora da amostra (holdout) inflaciona artificialmente a taxa de acerto.',q:'Adivinha antes de ver: Porque é obrigatório reservar um período holdout (out-of-sample)?',a:'Para testar se a regra captura um comportamento real do mercado ou se apenas memorizou o ruído histórico da amostra de treino.'},{id:'l5',t:'Lição 5 — Múltiplos Testes (Data Snooping)',txt:'Se testares 50 combinações diferentes de indicadores e timeframes, pelo menos 2 ou 3 parecerão lucrativas por puro acaso (p < 0.05). Quanto mais variantes testas, mais rigoroso tem de ser o critério.',q:'Adivinha antes de ver: O que acontece ao validar 100 variações de parâmetros sem correção estatística?',a:'A probabilidade de encontrar falsos positivos dispara; sem validação fora da amostra, a estratégia tende a falhar em tempo real.'}];function renderAcad(){acBox.innerHTML=lessons.map(function(L){var done=!!st[L.id];return '<div style="padding:14px;border:1px solid '+(done?'#22c55e':'#334155')+';border-radius:8px;background:#020617"><div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:6px"><strong style="color:#38bdf8;font-size:15px">'+L.t+'</strong><button type="button" class="aq-btn-44" data-ltog="'+L.id+'" style="min-height:32px;padding:4px 10px;border-color:'+(done?'#22c55e':'#475569')+'">'+(done?'✔ Visto (clique para rever)':'○ Marcar como visto')+'</button></div><p style="font-size:13px;margin:0 0 8px">'+L.txt+'</p><details style="background:#0f172a;padding:8px 10px;border-radius:6px"><summary style="cursor:pointer;color:#eab308;font-size:13px;font-weight:bold">'+L.q+'</summary><p style="font-size:13px;margin:8px 0 0;color:#e2e8f0">'+L.a+'</p></details></div>';}).join('');acBox.querySelectorAll('[data-ltog]').forEach(function(b){b.onclick=function(){var id=b.getAttribute('data-ltog');st[id]=!st[id];localStorage.setItem(AKEY,JSON.stringify(st));renderAcad();};});}renderAcad();}var alt50=document.getElementById('g3_alt50_box');if(alt50){fetch('https://api.binance.com/api/v3/ticker/24hr').then(function(r){return r.json();}).then(function(arr){var usdt=arr.filter(function(x){return /USDT$/.test(x.symbol)&&!/UPUSDT|DOWNUSDT|BEARUSDT|BULLUSDT|USDCUSDT|FDUSDUSDT|TUSDUSDT|BUSDUSDT|EURUSDT/.test(x.symbol);});usdt.sort(function(a,b){return parseFloat(b.quoteVolume)-parseFloat(a.quoteVolume);});var btcObj=usdt.find(function(x){return x.symbol==='BTCUSDT';});var btcChg=btcObj?parseFloat(btcObj.priceChangePercent):0;var top50=usdt.filter(function(x){return x.symbol!=='BTCUSDT';}).slice(0,50);var beat=top50.filter(function(x){return parseFloat(x.priceChangePercent)>btcChg;}).length;var idx=top50.length?Math.round((beat/top50.length)*100):0;var hr=new Date().toLocaleTimeString('pt-PT');var reg=idx>=75?'ALTCOIN SEASON ('+idx+'/100)':idx<=25?'BITCOIN SEASON ('+idx+'/100)':'NEUTRO / ROTAÇÃO ('+idx+'/100)';alt50.innerHTML='<div style="font-size:13px><b style="color:#eab308">'+reg+'</b> — '+beat+' de '+top50.length+' altcoins superam BTC ('+(btcChg>=0?'+':'')+btcChg.toFixed(2)+'%) | Atualizado às '+hr+'</div><div style="height:10px;background:#1e293b;border-radius:6px;margin-top:6px;overflow:hidden"><div style="width:'+idx+'%;height:100%;background:linear-gradient(90deg,#f97316,#22c55e)"></div></div>';var lst=document.getElementById('g3_alt50_list');if(lst)lst.innerHTML=top50.slice(0,8).map(function(x){var v=parseFloat(x.priceChangePercent);return '<div style="padding:4px 6px;background:#0f172a;border-radius:4px">'+x.symbol.replace('USDT','')+': <b style="color:'+(v>=btcChg?'#22c55e':'#94a3b8')+'">'+(v>=0?'+':'')+v.toFixed(2)+'%</b></div>';}).join('');}).catch(function(){alt50.textContent='Sem ligação à API Binance neste momento.';});}})();

