(function(){var CACHE_TTL=30000,MIN_GAP=1200,lastReq=0,reqCount=0,mem={};function nowStr(){return new Date().toLocaleTimeString('pt-PT');}function getCache(k){if(mem[k]&&(Date.now()-mem[k].ts)<CACHE_TTL)return mem[k];try{var s=JSON.parse(sessionStorage.getItem('aq_c_'+k)||'null');if(s&&(Date.now()-s.ts)<CACHE_TTL){mem[k]=s;return s;}}catch(e){}return null;}function setCache(k,data){var obj={ts:Date.now(),hr:nowStr(),data:data};mem[k]=obj;try{sessionStorage.setItem('aq_c_'+k,JSON.stringify(obj));}catch(e){}return obj;}function fetchBinance(key,url){var c=getCache(key);if(c)return Promise.resolve({ok:true,cached:true,hr:c.hr,data:c.data});var wait=Math.max(0,MIN_GAP-(Date.now()-lastReq));return new Promise(function(res){setTimeout(function(){lastReq=Date.now();reqCount++;fetch(url).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json();}).then(function(d){var s=setCache(key,d);res({ok:true,cached:false,hr:s.hr,data:d});}).catch(function(err){var old=mem[key];res({ok:false,err:err.message||'Sem ligação',stale:old?old.data:null,hr:old?old.hr:nowStr()});});},wait);});}function badgeR(hr,cached){return '<span class="selo-tag selo-R">[R] Binance • '+hr+(cached?' (cache)':'')+'</span>';}window.AQData={fetchBinance:fetchBinance,badgeR:badgeR,stats:function(){return{reqCount:reqCount,ttlSec:CACHE_TTL/1000};},renderWatchlist:function(elId){var el=document.getElementById(elId);if(!el)return;var syms=['BTCUSDT','ETHUSDT','SOLUSDT','BNBUSDT','XRPUSDT','EURUSDT'];el.innerHTML='<div style="font-size:12px;color:#94a3b8">A consultar lista de acompanhamento (só leitura)... [R]</div>';fetchBinance('tickers_all','https://api.binance.com/api/v3/ticker/24hr').then(function(r){if(!r.ok&&!r.stale){el.innerHTML='<div style="padding:8px;border:1px solid #ef4444;border-radius:6px;font-size:12px;color:#fca5a5"><b>[R] Sem ligação à API Binance</b> ('+r.hr+'). Verifica a tua ligação à internet e tenta novamente.</div>';return;}var arr=r.ok?r.data:r.stale;var rows=syms.map(function(s){var it=arr.find(function(x){return x.symbol===s;});if(!it)return '';var px=parseFloat(it.lastPrice),chg=parseFloat(it.priceChangePercent),hi=parseFloat(it.highPrice),lo=parseFloat(it.lowPrice),dec=px<10?4:2;return '<tr><td style="padding:5px;font-weight:bold">'+s.replace('USDT','/USDT')+'</td><td style="padding:5px">'+px.toFixed(dec)+' $</td><td style="padding:5px;color:'+(chg>=0?'#22c55e':'#ef4444')+'">'+(chg>=0?'+':'')+chg.toFixed(2)+'%</td><td style="padding:5px;font-size:11px;color:#94a3b8">'+lo.toFixed(dec)+' – '+hi.toFixed(dec)+'</td></tr>';}).join('');el.innerHTML='<div style="display:flex;justify-content:space-between;flex-wrap:wrap;gap:6px;margin-bottom:6px;font-size:12px">'+badgeR(r.hr,r.cached)+'<span style="color:#94a3b8">Só leitura • Pedidos sessão: '+reqCount+' • Cache: 30s</span></div><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr style="background:#1e293b;text-align:left"><th style="padding:5px">Par</th><th style="padding:5px">Último Preço [R]</th><th style="padding:5px">Var. 24h [R]</th><th style="padding:5px">Min–Máx 24h [R]</th></tr></thead><tbody>'+rows+'</tbody></table><p style="font-size:11px;color:#94a3b8;margin:6px 0 0">Atribuição: Cotações públicas fornecidas via API REST Binance (uso informativo/educativo; sem execução de ordens).</p>';});}};var wl=document.getElementById('g3_watchlist_box');if(wl)window.AQData.renderWatchlist('g3_watchlist_box');})();

(function(){var sec=document.getElementById('bot10_sec');if(!sec)return;var btn=document.getElementById('btn_bot01_calc');if(btn)btn.onclick=function(){var arr=(document.getElementById('bot01_r_inp').value||'').split(/[,;\s]+/).map(function(x){return parseFloat(x.replace(',','.'));}).filter(function(x){return !isNaN(x);});var out=document.getElementById('bot01_metrics_out');if(!arr.length){out.textContent='Insere pelo menos 1 valor numérico em R.';return;}localStorage.setItem('aq_bot01_trades_v1',JSON.stringify(arr));var n=arr.length,sum=arr.reduce(function(a,b){return a+b;},0),exp=sum/n,wins=arr.filter(function(x){return x>0;}).length,wr=(wins/n)*100;var sd=n>1?Math.sqrt(arr.reduce(function(a,b){return a+Math.pow(b-exp,2);},0)/(n-1)):0,se=n>1?sd/Math.sqrt(n):0,lo=exp-1.96*se,hi=exp+1.96*se;var srt=arr.slice().sort(function(a,b){return b-a;}),noTop2=srt.slice(2),expNo2=noTop2.length?noTop2.reduce(function(a,b){return a+b;},0)/noTop2.length:0;out.innerHTML='<b>n = '+n+'</b> | Win Rate: <b>'+wr.toFixed(1)+'%</b> | R Acumulado: <b style="color:'+(sum>=0?'#22c55e':'#ef4444')+'">'+(sum>=0?'+':'')+sum.toFixed(2)+' R</b> | Expectância: <b>'+(exp>=0?'+':'')+exp.toFixed(3)+' R</b><br>IC 95%: <b>['+lo.toFixed(3)+' R , '+hi.toFixed(3)+' R]</b> | Expectância sem Top 2 outliers: <b>'+(expNo2>=0?'+':'')+expNo2.toFixed(3)+' R</b>';};var savedArr=JSON.parse(localStorage.getItem('aq_bot01_trades_v1')||'[]');if(savedArr.length){document.getElementById('bot01_r_inp').value=savedArr.join(', ');if(btn)btn.click();}function showB2(){var bx=document.getElementById('bot02_saved_box');if(!bx)return;var d=JSON.parse(localStorage.getItem('aq_bot02_prereg_v1')||'null');if(d)bx.innerHTML='<div style="padding:10px;border:1px solid #22c55e;border-radius:8px;background:#052e16"><b style="color:#4ade80">✔ Hipótese Bot 02 Pré-Registada ('+d.ts+'):</b> '+d.sym+' — '+d.hyp+' | Critério de paragem: '+d.stop+'</div>';}var f2=document.getElementById('bot02_form');if(f2)f2.onsubmit=function(ev){ev.preventDefault();localStorage.setItem('aq_bot02_prereg_v1',JSON.stringify({ts:new Date().toLocaleString('pt-PT'),sym:document.getElementById('b2_sym').value,hyp:document.getElementById('b2_hyp').value,stop:document.getElementById('b2_stop').value}));showB2();};showB2();})();

